package tokenanalytics

import (
	"strings"
	"sync/atomic"
	"testing"
	"time"

	"github.com/goccy/go-json"
	"github.com/stretchr/testify/require"

	"github.com/ice-blockchain/heimdall/accounts"
)

func TestTransactionValidation(t *testing.T) {
	t.Skip("TODO: remove when FE is ready")
	tu := &tokenAnalyticsUsers{
		cfg: &config{BondingCurve: struct {
			SmartContractAddress                string                         `yaml:"smartContractAddress"`
			BurnAddress                         string                         `yaml:"burnAddress"`
			TokenFactorySmartContractAddress    string                         `yaml:"tokenFactorySmartContractAddress"`
			BondingCurveProgressUpdateFrequency time.Duration                  `yaml:"bondingCurveProgressUpdateFrequency"`
			CreateTokenDefaults                 map[string]createTokenDefaults `yaml:"createTokenDefaults" mapstructure:"createTokenDefaults"`
			TransactionValidationFeeSlippage    float64                        `yaml:"transactionValidationFeeSlippage"`
		}{CreateTokenDefaults: make(map[string]createTokenDefaults), TransactionValidationFeeSlippage: 0.05, SmartContractAddress: "0x4ab1807ff59a391503b0c8e28d2647bd9a7ecda1"}},
		bscFees: new(atomic.Pointer[accounts.Fee]),
	}
	tu.bscFees.Store(&accounts.Fee{MaxFeePerGas: "100", MaxPriorityFeePerGas: "100"})
	tu.cfg.BondingCurve.CreateTokenDefaults["post"] = createTokenDefaults{
		InitialPrice:           "10000",
		FinalPrice:             "100000",
		EmissionVolume:         "1000000000000000000000",
		BondingCurveAlgAddress: "0x000000000000000000000000000000000000dead",
		FeeSponsorAddress:      "0x000000000000000000000000000000000000dead",
		FeeSponsorId:           "post",
	}
	tu.cfg.BondingCurve.CreateTokenDefaults["profile"] = createTokenDefaults{
		InitialPrice:           "1000000",
		FinalPrice:             "100000000",
		EmissionVolume:         "1000000000000000000000",
		BondingCurveAlgAddress: "0x000000000000000000000000000000000000dead",
		FeeSponsorAddress:      "0x000000000000000000000000000000000000dead",
		FeeSponsorId:           "profile",
	}
	t.Run("tx gets rejected when fee is higher than expected", func(t *testing.T) {
		txWithExceedingFeesData := `{
          "kind": "UserOperations",
          "maxFeePerGas": "110",
          "userOperations": [
            {
              "to": "0x4Ab1807ff59a391503b0C8E28D2647bd9A7ecdA1",
              "data": ""
            },
            {
              "to": "0x4Ab1807ff59a391503b0C8E28D2647bd9A7ecdA1",
              "data": ""
            }
          ],
          "feeSponsorId": "fs-01jg7-2dotc-esmbtjcn9udvpvk8"
        }`
		var txWithExceedingFees accounts.TransactionPayload
		require.NoError(t, json.Unmarshal([]byte(txWithExceedingFeesData), &txWithExceedingFees))
		require.Error(t, tu.ValidateTransaction(txWithExceedingFees), ErrValidationFailed)
	})
	t.Run("tx gets passed when fee is below threshold or fee sponsor id is not set and valid curve params passed", func(t *testing.T) {
		txWithLowFeesData := `{
          "kind": "UserOperations",
          "maxFeePerGas": "99",
          "userOperations": [
            {
              "to": "0x4Ab1807ff59a391503b0C8E28D2647bd9A7ecdA1",
              "data": ""
            },
            {
              "to": "0x4Ab1807ff59a391503b0C8E28D2647bd9A7ecdA1",
              "data": ""
            }
          ],
          "feeSponsorId": "fs-01jg7-2dotc-esmbtjcn9udvpvk8"
        }`
		var txWithLowFees accounts.TransactionPayload
		require.NoError(t, json.Unmarshal([]byte(txWithLowFeesData), &txWithLowFees))
		require.NoError(t, tu.ValidateTransaction(txWithLowFees))
		var txNoFees accounts.TransactionPayload
		require.NoError(t, json.Unmarshal([]byte(strings.ReplaceAll(txWithLowFeesData, "\"maxFeePerGas\": \"99\",", "")), &txNoFees))
		require.NoError(t, tu.ValidateTransaction(txNoFees))
		require.NoError(t, json.Unmarshal([]byte(strings.ReplaceAll(txWithLowFeesData, ",\n          \"feeSponsorId\": \"fs-01jg7-2dotc-esmbtjcn9udvpvk8\"", "")), &txNoFees))
		require.NoError(t, tu.ValidateTransaction(txNoFees))
	})
	t.Run("tx gets passed when non bonding-curve is called", func(t *testing.T) {
		txNotToBondingCurveData := `{
          "kind": "UserOperations",
          "userOperations": [
            {
              "to": "0x000000000000000000000000000000000001dead",
              "data": ""
            },
            {
              "to": "0x000000000000000000000000000000000002dead",
              "data": ""
            }
          ]
        }`
		var txNotToBondingCurve accounts.TransactionPayload
		require.NoError(t, json.Unmarshal([]byte(txNotToBondingCurveData), &txNotToBondingCurve))
		require.NoError(t, tu.ValidateTransaction(txNotToBondingCurve))
	})
	t.Run("bonding curve params are validated when non-first swap occurs", func(t *testing.T) {
		txFirstSwapData := `{
          "kind": "UserOperations",
          "userOperations": [
            {
              "to": "0x4Ab1807ff59a391503b0C8E28D2647bd9A7ecdA1",
              "data": ""
            },
            {
              "to": "0x4Ab1807ff59a391503b0C8E28D2647bd9A7ecdA1",
              "data": ""
            }
          ]
        }`
		var txFirstSwap accounts.TransactionPayload
		require.NoError(t, json.Unmarshal([]byte(txFirstSwapData), &txFirstSwap))
		err := tu.ValidateTransaction(txFirstSwap)
		require.Error(t, err, ErrValidationFailed)
		require.True(t, strings.Contains(err.Error(), "expected 0x000000000000000000000000000000000000dead, got 0x0000000000000000000000000000000000000000"))
	})
}
